// Must be the first import of the Worker: it lets libsodium load in workerd, which
// refuses to compile WebAssembly from bytes. The .wasm file is generated by
// `pnpm run sodium-wasm` from the installed libsodium, so it always matches it.
import { useCompiledSodiumWasm } from "@map-diary/crypto/workerd";
import sodiumWasm from "./generated/libsodium-sumo.wasm";

useCompiledSodiumWasm(sodiumWasm);
